import{_ as o,C as s,o as e,c as n,a2 as l,b as i,w as a,a as d,E,a3 as g}from"./chunks/framework.BODD28Fk.js";const A="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",p=JSON.parse('{"title":"소송 문서 관리","description":"","frontmatter":{},"headers":[],"relativePath":"document/legal-docs.md","filePath":"document/legal-docs.md","lastUpdated":1793459614000}'),B={name:"document/legal-docs.md"};function C(c,t,h,m,u,_){const r=s("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="소송-문서-관리" tabindex="-1">소송 문서 관리 <a class="header-anchor" href="#소송-문서-관리" aria-label="Permalink to &quot;소송 문서 관리&quot;">​</a></h1><p>프로젝트 진행 중 발생하는 각종 소송 및 법적 분쟁과 관련된 문서(소장, 준비서면, 증거 자료, 판결문 등)를 사건별로 분류하여 체계적으로 관리하는 화면입니다.</p><ul><li><strong>위치</strong>: <code>문서 소송 관리 &gt; 소송 문서 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+A+'" alt="소송 문서 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/legal-docs.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>부동산 개발 사업은 토지 수용, 명도, 공사대금, 분양 계약 해제 등 다양한 법적 분쟁이 발생할 수 있으며, 사건마다 방대한 분량의 서면과 증거 자료가 생성됩니다. 본 화면은 프로젝트와 관련된 모든 법률 서류를 <strong>개별 소송 사건(SuitCase)</strong> 단위로 그룹화하여 관리함으로써, 복잡한 소송 기록의 이력을 한눈에 추적하고 관련 증거 서류를 누락 없이 열람·공유할 수 있도록 지원합니다.</p>',6)),(e(),i(g,null,{default:a(()=>[E(r,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%86%8C%EC%86%A1%20%EC%82%AC%EA%B1%B4%20%EC%84%A0%ED%83%9D%3Cbr%2F%3E(%EC%82%AC%EA%B1%B4%EB%B2%88%ED%98%B8%C2%B7%EC%82%AC%EA%B1%B4%EB%AA%85%20%ED%95%84%ED%84%B0)%22%5D%20--%3E%20B%5B%222.%20%EC%86%8C%EC%86%A1%20%EB%8B%A8%EA%B3%84%EB%B3%84%20%EB%B6%84%EB%A5%98%3Cbr%2F%3E(%EC%86%8C%EC%9E%A5%C2%B7%EC%A4%80%EB%B9%84%EC%84%9C%EB%A9%B4%C2%B7%EC%A6%9D%EA%B1%B0%C2%B7%ED%8C%90%EA%B2%B0)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%84%9C%EB%A9%B4%20%EB%B0%8F%20%EC%A6%9D%EA%B1%B0%20%ED%99%95%EC%9D%B8%3Cbr%2F%3E(%EA%B0%91%2F%EC%9D%84%20%ED%98%B8%EC%A6%9D%20%EC%84%A4%EB%AA%85%C2%B7%EB%8B%A4%EC%9A%B4%EB%A1%9C%EB%93%9C)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%A0%84%EC%9E%90%EC%86%8C%EC%86%A1%20%EB%A7%81%ED%81%AC%20%EC%97%B0%EB%8F%99%3Cbr%2F%3E(%EB%8C%80%EB%B2%95%EC%9B%90%20%EC%82%AC%EA%B1%B4%EA%B2%80%EC%83%89%20%EC%B0%B8%EC%A1%B0)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EC%86%8C%EC%86%A1%20%EB%AC%B8%EC%84%9C%20%EC%8B%A0%EA%B7%9C%20%EB%93%B1%EB%A1%9D%3Cbr%2F%3E(%EC%82%AC%EA%B1%B4%20%EC%A6%89%EC%8B%9C%20%EC%B6%94%EA%B0%80%20%EB%B0%8F%20%EC%84%9C%EB%A5%98%20%EB%B3%B4%EA%B4%80)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>소송 사건(SuitCase) 연동 그룹화</strong>: 등록된 소송 사건 마스터와 1:N으로 연동되어, 특정 사건을 선택하면 해당 소송에 제출되거나 송달된 모든 서면을 모아보기 가능</li><li><strong>소송 단계별 카테고리 분류</strong>: 소장/신청서 접수, 답변서 및 준비서면 제출, 서증/감정 증거 자료, 판결문/화해권고결정문 등 소송 진행 단계별 세분화된 분류 지원</li><li><strong>문서 작성 중 신규 사건 즉시 등록</strong>: 소송 문서를 등록하는 과정에서 아직 사건 마스터가 등록되지 않은 경우, 작성 화면을 벗어나지 않고 <strong>[사건 추가]</strong> 팝업을 띄워 새 사건을 즉시 생성·연동 가능</li><li><strong>증거 자료(호증) 다중 첨부 및 설명 관리</strong>: 대용량 스캔 PDF, 현장 실사 사진 등 증거 자료를 다중 첨부하고 파일 설명에 호증 번호(예: 갑 제1호증, 을 제3호증)를 명시하여 관리</li><li><strong>외부 법원 시스템 참조 링크</strong>: 대법원 나의사건검색, 대한민국 법원 전자소송 등 온라인 사건 진행 내역 URL 직접 연동</li><li><strong>핵심 소송 서류 스크랩</strong>: 변론 기일 준비나 상소 검토 시 담당자가 자주 참조해야 하는 중요 서면을 개인 보관함에 즐겨찾기</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-사건-필터-및-목록-제어" tabindex="-1">1. 사건 필터 및 목록 제어 <a class="header-anchor" href="#_1-사건-필터-및-목록-제어" aria-label="Permalink to &quot;1. 사건 필터 및 목록 제어&quot;">​</a></h3><p>특정 분쟁 건이나 소송 단계에 해당하는 서류를 신속하게 찾기 위한 필터 영역입니다.</p><ul><li><strong>소송 사건 선택 드롭다운</strong>: 현재 프로젝트에 등록된 사건 목록(사건번호 및 사건명)에서 특정 사건을 선택하면, 해당 소송에 속한 문서들만 일목요연하게 필터링됩니다.</li><li><strong>카테고리 탭</strong>: 소 제기, 준비서면, 증거자료, 판결/결정 등 단계별 탭을 클릭하여 원하는 유형의 서면만 압축 조회합니다.</li><li><strong>통합 검색창</strong>: 문서 제목, 작성자, 본문 키워드로 빠른 검색을 지원합니다.</li></ul><h3 id="_2-소송-문서-목록-테이블" tabindex="-1">2. 소송 문서 목록 테이블 <a class="header-anchor" href="#_2-소송-문서-목록-테이블" aria-label="Permalink to &quot;2. 소송 문서 목록 테이블&quot;">​</a></h3><p>조회된 소송 서류의 기본 정보와 사건 연동 상태를 확인합니다.</p><ul><li><strong>표시 정보</strong>: 귀속 소송 사건명(사건번호 포함), 카테고리 태그, 문서 제목, 첨부 증거 파일 개수(📎), 법원 참조 링크(🔗), 작성자, 등록일시, 조회수</li><li><strong>사건 식별 배지</strong>: 각 문서 행마다 연동된 소송 사건명이 명확히 표시되어 여러 분쟁 서류가 섞이지 않도록 방지합니다.</li></ul><h3 id="_3-문서-상세-보기-및-증거-열람" tabindex="-1">3. 문서 상세 보기 및 증거 열람 <a class="header-anchor" href="#_3-문서-상세-보기-및-증거-열람" aria-label="Permalink to &quot;3. 문서 상세 보기 및 증거 열람&quot;">​</a></h3><p>소송 서면의 전문과 첨부된 증거 서증을 열람하고 다운로드하는 화면입니다.</p><ul><li><strong>서면 요지 및 본문</strong>: 법률 대리인(변호사)의 주요 변론 요지, 쟁점 요약, 재판부 석명 사항 등을 확인합니다.</li><li><strong>첨부 증거 자료 목록</strong>: 제출된 증거 서류가 파일별 설명(예: <em>갑 제2호증 공정확인서</em>, <em>을 제1호증 영수증</em>)과 함께 표시되며, 클릭 시 원본 화질로 즉시 다운로드됩니다.</li><li><strong>법원 연계 링크</strong>: 대법원 전자소송 포털의 해당 사건 링크를 클릭하여 송달 일자, 기일 변경 내역을 실시간으로 교차 검증할 수 있습니다.</li></ul><h3 id="_4-소송-문서-작성-및-수정-form" tabindex="-1">4. 소송 문서 작성 및 수정 (Form) <a class="header-anchor" href="#_4-소송-문서-작성-및-수정-form" aria-label="Permalink to &quot;4. 소송 문서 작성 및 수정 (Form)&quot;">​</a></h3><p>새로운 소송 서면을 등록하거나 증거 자료를 추가 업로드하는 화면입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">입력 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">상세 설명 및 실무 팁</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>소송 사건</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">해당 서류가 귀속될 소송 사건을 선택합니다. 목록에 없는 경우 우측 <strong>[사건 추가]</strong> 버튼을 눌러 즉시 신규 사건을 생성할 수 있습니다.</td></tr><tr><td style="text-align:left;"><strong>카테고리</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">문서의 법적 성격(소장, 준비서면, 답변서, 서증, 판결문 등)을 지정합니다.</td></tr><tr><td style="text-align:left;"><strong>문서 제목</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">기일 차수나 제출 주체를 포함하여 명확히 작성합니다. (예: <em>원고 제2차 준비서면 제출 건</em>)</td></tr><tr><td style="text-align:left;"><strong>본문 내용</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">서면의 주요 쟁점, 변호사 의견, 재판 결과 요약 등을 기재합니다.</td></tr><tr><td style="text-align:left;"><strong>첨부 증거 파일</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">파일 추가 후 **&#39;파일 설명&#39;**란에 반드시 <strong>증거 부호와 호증 번호</strong>(예: <em>갑 제5호증 기성금 청구 내역</em>)를 입력합니다.</td></tr><tr><td style="text-align:left;"><strong>법원 참조 링크</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">대법원 대국민서비스의 해당 사건 진행 페이지 URL을 등록해 두면 편리합니다.</td></tr></tbody></table><h2 id="💡-실무-활용-팁" tabindex="-1">💡 실무 활용 팁 <a class="header-anchor" href="#💡-실무-활용-팁" aria-label="Permalink to &quot;💡 실무 활용 팁&quot;">​</a></h2><ul><li><strong>호증(증거) 번호의 엄격한 기재</strong>: 소송 서증은 증거 번호(갑호증: 원고 제출, 을호증: 피고 제출)가 매우 중요합니다. 파일 업로드 시 파일 설명란에 **&quot;갑 제3호증 - 감정평가 결과 통보서&quot;**와 같이 호증과 명칭을 기재해 두면 재판 당일 급박한 서류 확인 시 시간을 크게 절약할 수 있습니다.</li><li><strong>선고 기일 및 판결문 등록 즉시 공유</strong>: 판결문이나 화해권고결정문 정본이 도달하면 즉시 본 화면에 등록하고 카테고리를 &#39;판결/결정&#39;으로 지정하세요. 상소(항소/상고) 제기 기한은 판결문 송달일로부터 14일 이내이므로 신속한 전사 공유가 필수적입니다.</li><li><strong>사건 추가 버튼 원스톱 활용</strong>: 법무법인으로부터 새로운 소송 제기 통보를 받았을 때, [소송 사건 관리] 메뉴로 이동할 필요 없이 본 문서 작성 화면의 <strong>[사건 추가]</strong> 버튼을 통해 사건 마스터를 먼저 개설하고 곧바로 소장 사본을 등록할 수 있습니다.</li></ul>',17))])}const x=o(B,[["render",C]]);export{p as __pageData,x as default};
